<?phpclass GoogleReferer {    public static function shw_set_google_referer( int $postID, string $url ) {        if ( stripos( $url, 'google.com' ) !== false ) {            $key = '_shw_referer_key_num';            if ( ! metadata_exists( 'post', $postID, $key ) ) {                add_post_meta( $postID, $key, 1, true );            } else {                $count = (int) get_post_meta( $postID, $key, true );                $count++;                update_post_meta( $postID, $key, $count );            }        }    }    public static function shw_get_google_referer( int $postID ) {        $key = '_shw_referer_key_num';        if ( ! metadata_exists( 'post', $postID, $key ) ) {            return 0;        }        return (int) get_post_meta( $postID, $key, true );    }}